CustomField.formula:
IF(RecordType.Name == 'Patrimonial'  && (ISPICKVAL(StageName, "Cerrada Ganada")),
          'Cliente',
       IF((RecordType.Name == 'Patrimonial' || RecordType.Name =='' )  && (ISPICKVAL(StageName, "Cerrada Perdida")),
          'Descartado',
          IF(RecordType.Name == 'Patrimonial'  && !(ISPICKVAL(StageName, "Cerrada Ganada") || ISPICKVAL(StageName, "Cerrada Perdida")),
       'Prospecto', ''
        )

    )
)
